"""Original glyphs for the user's second October 25 acceptance list (A/B).
No product integration is implied. Existing published records are immutable.
"""
from core import p,r,c,g,accent,PALE,TEAL,INK
ADDITIONS={}
REQUIREMENTS=[]
def add(domain,id,en,ja,meaning,body,section='A',role='command'):
    item=dict(id=id,name=en,nameJa=ja,description=meaning,descriptionJa=ja+'。'+('現在の代用を専用図柄に置き換えるためのアイコンです。' if section=='A' else '今後の機能向けの専用アイコンです。'),body=body,family=id,role=role,tags=[en.lower(),ja,'oct25-request'],sources=['cax-oct25-additional-request'])
    ADDITIONS.setdefault(domain,[]).append(item)
    REQUIREMENTS.append(dict(id=domain.lower()+'-'+id,section=section,meaning=meaning,nameJa=ja,status='new-art',consumer_ui_integrated=False))
